func IsLocalEndpoint(url string) bool {
	return !MatchesScheme(url) && !MatchesScpLike(url)
}

func (r *Repository) clone(ctx context.Context, o *CloneOptions) error {
	if trace.Performance.Enabled() {
		start := time.Now()
		defer func() {
			url := ""
			if o != nil {
				url = o.URL
			}
			trace.Performance.Printf("performance: %.9f s: git command: git clone %s", time.Since(start).Seconds(), url)
		}()
	}

	if err := o.Validate(); err != nil {
		return err
	}

	// PlainClone and Clone have two different execution paths, the former
	// populates r.wt, while the latter doesn't. A refactoring is in order to
	// better align both approaches.
	if r.wt == nil {
		r.wt = o.worktree
	}

	c := &config.RemoteConfig{
		Name:   o.RemoteName,
		URLs:   []string{o.URL},
		Fetch:  r.cloneRefSpec(o),
		Mirror: o.Mirror,
	}

	if _, err := r.CreateRemote(c); err != nil {
		return err
	}

	// When the repository to clone is on the local machine,
	// instead of using hard links, automatically setup .git/objects/info/alternates
	// to share the objects with the source repository
	if o.Shared {
		if !url.IsLocalEndpoint(o.URL) {
			return ErrAlternatePathNotSupported
		}
		altpath := o.URL
		remoteRepo, err := PlainOpen(o.URL)
		if err != nil {
			return fmt.Errorf("failed to open remote repository: %w", err)
		}
		defer func() { _ = remoteRepo.Close() }()
		conf, err := remoteRepo.Config()
		if err != nil {
			return fmt.Errorf("failed to read remote repository configuration: %w", err)
		}
		if !conf.Core.IsBare {
			altpath = path.Join(altpath, GitDirName)
		}
		if err := r.Storer.AddAlternate(altpath); err != nil {
			return fmt.Errorf("failed to add alternate file to git objects dir: %w", err)
		}
	}

	ref, err := r.fetchAndUpdateReferences(ctx, &FetchOptions{
		RefSpecs:      c.Fetch,
		Depth:         o.Depth,
		ClientOptions: o.ClientOptions,
		Progress:      o.Progress,
		Tags:          o.Tags,
		RemoteName:    o.RemoteName,
		Filter:        o.Filter,
	}, o.ReferenceName)

	hr, err1 := r.Storer.Reference(plumbing.HEAD)
	if err1 == nil && hr.Target() == plumbing.Invalid {
		_ = r.Storer.SetReference(plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.Master))
	}

	if err != nil {
		return err
	}

	err = r.setWorktreeAndStoragePaths()
	if err != nil {
		return err
	}

	if r.wt != nil && !o.NoCheckout {
		w, err := r.Worktree()
		if err != nil {
			return err
		}

		head, err := r.Head()
		if err != nil {
			return err
		}

		if err := w.Reset(&ResetOptions{
			Mode:   MergeReset,
			Commit: head.Hash(),
		}); err != nil {
			return err
		}

		if o.RecurseSubmodules != NoRecurseSubmodules {
			if err := w.updateSubmodules(ctx, &SubmoduleUpdateOptions{
				RecurseSubmodules: o.RecurseSubmodules,
				Depth: func() int {
					if o.ShallowSubmodules {
						return 1
					}
					return 0
				}(),
				ClientOptions: o.ClientOptions,
			}); err != nil {
				return err
			}
		}
	}

	if err := r.updateRemoteConfigIfNeeded(o, c, ref); err != nil {
		return err
	}

	if !o.Mirror && ref.Name().IsBranch() {
		branchRef := ref.Name()
		branchName := strings.Split(string(branchRef), "refs/heads/")[1]

		b := &config.Branch{
			Name:  branchName,
			Merge: branchRef,
		}

		if o.RemoteName == "" {
			b.Remote = "origin"
		} else {
			b.Remote = o.RemoteName
		}

		if err := r.CreateBranch(b); err != nil {
			return err
		}
	}

	return nil
}

func (s *OptionsSuite) TestCloneOptionsValidate_RelativeDotDot() {
	for _, input := range []string{"../../", "../foo", ".."} {
		o := &CloneOptions{URL: input}
		err := o.Validate()
		s.NoError(err, "input %q", input)
		s.True(filepath.IsAbs(o.URL),
			"..-relative URL %q must be resolved to absolute after Validate, got %q", input, o.URL)
	}
}

func MatchesScheme(url string) bool {
	return isSchemeRegExp.MatchString(url)
}

func MatchesScpLike(url string) bool {
	if !scpLikeURLRegExp.MatchString(url) {
		return false
	}
	// Mirror canonical Git's url_is_local_not_ssh in connect.c[1] for
	// the cases the regex above cannot disambiguate by itself: a URL
	// is treated as a local path (not SCP-style SSH) when a `/`
	// precedes the first `:` (e.g. `./relative:path`,
	// `/abs/with:colon/file`), or — on Windows only — when it has a
	// DOS drive prefix like `C:foo` where the host is a single
	// ASCII letter.
	//
	// [1]: https://github.com/git/git/blob/v2.54.0/connect.c#L710-L716
	if before, _, _ := strings.Cut(url, ":"); strings.Contains(before, "/") {
		return false
	}
	if runtime.GOOS == "windows" && hasDosDrivePrefix(url) {
		return false
	}
	return true
}

func (c *RemoteConfig) IsFirstURLLocal() bool {
	return url.IsLocalEndpoint(c.URLs[0])
}

