func CloneContext(
	ctx context.Context, s storage.Storer, worktree billy.Filesystem, o *CloneOptions,
) (*Repository, error) {
	r, err := Init(s, withPartialInit())
	if err != nil {
		return nil, err
	}

	if o == nil {
		o = &CloneOptions{}
	}
	o.worktree = worktree

	return r, r.clone(ctx, o)
}

func PlainCloneContext(ctx context.Context, path string, o *CloneOptions) (*Repository, error) {
	empty, err := checkTargetDirIsEmpty(path)
	if err != nil {
		return nil, err
	}
	if !empty {
		return nil, fmt.Errorf("%w %s", ErrTargetDirNotEmpty, path)
	}

	isBare := o.Bare
	if o.Mirror {
		isBare = true
	}
	// Record whether the directory existed before we touched it so we can
	// roll back correctly on failure, matching the behaviour of `git clone`:
	//   - directory didn't exist → remove it entirely on failure
	//   - directory already existed (empty) → remove only content we added
	_, preErr := os.Stat(path)
	dirPreexisted := !os.IsNotExist(preErr)

	var initOptions []InitOption
	if !o.AllowEmptyRepo {
		initOptions = append(initOptions, withPartialInit())
	}

	r, err := PlainInit(path, isBare, initOptions...)
	if err != nil {
		return nil, err
	}

	if err := r.clone(ctx, o); err != nil {
		if o.AllowEmptyRepo && errors.Is(err, transport.ErrEmptyRemoteRepository) {
			return r, nil
		}
		_ = r.Close()
		if dirPreexisted {
			// Restore the directory to its original empty state.
			_ = os.RemoveAll(filepath.Join(path, GitDirName))
		} else {
			// We created the directory; remove it entirely.
			_ = os.RemoveAll(path)
		}
		return r, err
	}

	return r, nil
}

func (r *Remote) Push(o *PushOptions) error {
	return r.PushContext(context.Background(), o)
}

func (r *Remote) PushContext(ctx context.Context, o *PushOptions) (err error) {
	if trace.Performance.Enabled() {
		start := time.Now()
		defer func() {
			trace.Performance.Printf("performance: %.9f s: git command: git push", time.Since(start).Seconds())
		}()
	}

	if err := o.Validate(); err != nil {
		return err
	}

	if o.RemoteName != r.c.Name {
		return fmt.Errorf("remote names don't match: %s != %s", o.RemoteName, r.c.Name)
	}

	if o.RemoteURL == "" && len(r.c.URLs) > 0 {
		o.RemoteURL = r.c.URLs[len(r.c.URLs)-1]
	}

	cl, req, err := newClient(o.RemoteURL, o.ClientOptions)
	if err != nil {
		return err
	}

	req.Command = transport.ReceivePackService
	sess, err := cl.Handshake(ctx, req)
	if err != nil {
		return err
	}
	defer ioutil.CheckClose(sess, &err)

	rRefs, err := sess.GetRemoteRefs(ctx, nil)
	if err != nil {
		return err
	}

	remoteRefs := referenceStorageFromRefs(rRefs.References, true)
	if err := r.checkRequireRemoteRefs(o.RequireRemoteRefs, remoteRefs); err != nil {
		return err
	}

	return r.sendPack(ctx, sess, remoteRefs, o)
}

func (r *Remote) sendPack(ctx context.Context, sess transport.Session, remoteRefs storer.ReferenceStorer, o *PushOptions) error {
	isDelete := false
	allDelete := true
	for _, rs := range o.RefSpecs {
		if rs.IsDelete() {
			isDelete = true
		} else {
			allDelete = false
		}
		if isDelete && !allDelete {
			break
		}
	}

	// TODO: support delete-refs
	caps := sess.Capabilities() // server capabilities
	if isDelete && !caps.Supports(capability.DeleteRefs) {
		return ErrDeleteRefNotSupported
	}

	if o.Force {
		for i := 0; i < len(o.RefSpecs); i++ {
			rs := &o.RefSpecs[i]
			if !rs.IsForceUpdate() && !rs.IsDelete() {
				o.RefSpecs[i] = config.RefSpec("+" + rs.String())
			}
		}
	}

	localRefs, err := reference.References(r.s)
	if err != nil {
		return err
	}

	cmds := make([]*packp.Command, 0)
	if err := r.addReferencesToUpdate(o.RefSpecs, localRefs, remoteRefs, &cmds, o.Prune, o.ForceWithLease); err != nil {
		return err
	}

	if o.FollowTags {
		if err := r.addReachableTags(localRefs, remoteRefs, &cmds); err != nil {
			return err
		}
	}

	if len(cmds) == 0 {
		return NoErrAlreadyUpToDate
	}

	objects := objectsToPush(cmds)
	haves, err := referencesToHashes(remoteRefs)
	if err != nil {
		return err
	}

	stop, err := r.s.Shallow()
	if err != nil {
		return err
	}

	// if we have shallow we should include this as part of the objects that
	// we are aware.
	haves = append(haves, stop...)

	var hashesToPush []plumbing.Hash
	// Avoid the expensive revlist operation if we're only doing deletes.
	if !allDelete {
		hashesToPush, err = revlist.Objects(r.s, objects, haves)
		if err != nil {
			return err
		}
	}

	if len(hashesToPush) == 0 {
		allDelete = true
		for _, command := range cmds {
			if command.Action() != packp.Delete {
				allDelete = false
				break
			}
		}
	}

	if err := pushHashes(ctx, sess, r.s, cmds, hashesToPush, allDelete, o); err != nil {
		return err
	}

	return r.updateRemoteReferenceStorage(cmds)
}

func (o *PushOptions) Validate() error {
	if o.RemoteName == "" {
		o.RemoteName = DefaultRemoteName
	}

	if len(o.RefSpecs) == 0 {
		o.RefSpecs = []config.RefSpec{
			config.RefSpec(config.DefaultPushRefSpec),
		}
	}

	for _, r := range o.RefSpecs {
		if err := r.Validate(); err != nil {
			return err
		}
	}

	return nil
}

